import { CaptchaTaskComponent } from "@hunt/puzzle-components";
import { createRoot } from "react-dom/client";
import { CAPTCHA_ELEMENTS } from "./data";

const captcha_elem = document.getElementById("captcha-root");
if (captcha_elem) {
  const root = createRoot(captcha_elem);
  root.render(
    <CaptchaTaskComponent
      taskSlug="captcha_task"
      flavorText="Help the Elder Drifts Puzzmon identify all of the non-compliant images"
      refreshTimeInSeconds={30}
      localElements={CAPTCHA_ELEMENTS}
    />,
  );
} else {
  console.error(
    "Could not mount because #captcha-root was nowhere to be found",
  );
}
